import React, { useEffect, useMemo, useRef, useState } from "react";
import Watchlist from "./Watchlist";

const DEFAULT_WATCHLIST_PREFIX = "Watchlist";

function buildSuggestions(query, symbols) {
  if (!query) return [];
  const normalized = query.trim().toUpperCase();
  if (!normalized) return [];
  return symbols.filter((symbol) => symbol.includes(normalized)).slice(0, 6);
}

export default function WatchlistManager({
  watchlists,
  activeWatchlistId,
  allSymbols,
  selectedSymbol,
  getStockBySymbol,
  flashMap,
  onSwitchWatchlist,
  onAddWatchlist,
  onRenameWatchlist,
  onDeleteWatchlist,
  onAddSymbol,
  onRemoveSymbol,
  onMoveSymbol,
  onSelectSymbol,
  onReorderSymbol,
}) {
  const [newWatchlistName, setNewWatchlistName] = useState("");
  const [renameValue, setRenameValue] = useState("");
  const [symbolQuery, setSymbolQuery] = useState("");
  const [isCollapsed, setIsCollapsed] = useState(false);
  const [contextMenu, setContextMenu] = useState(null);
  const contextMenuRef = useRef(null);

  const activeWatchlist = useMemo(
    () => watchlists.find((list) => list.id === activeWatchlistId),
    [watchlists, activeWatchlistId]
  );

  const nextDefaultWatchlistName = useMemo(() => {
    const nextIndex = watchlists.length + 1;
    return `${DEFAULT_WATCHLIST_PREFIX} ${nextIndex}`;
  }, [watchlists.length]);

  useEffect(() => {
    setRenameValue(activeWatchlist?.name ?? "");
  }, [activeWatchlist]);

  useEffect(() => {
    function handleClickOutside(event) {
      if (!contextMenuRef.current) return;
      if (!contextMenuRef.current.contains(event.target)) {
        setContextMenu(null);
      }
    }

    if (contextMenu) {
      document.addEventListener("click", handleClickOutside);
    }

    return () => document.removeEventListener("click", handleClickOutside);
  }, [contextMenu]);

  const availableSymbols = useMemo(() => {
    if (!activeWatchlist) return allSymbols;
    return allSymbols.filter((symbol) => !activeWatchlist.symbols.includes(symbol));
  }, [allSymbols, activeWatchlist]);

  const suggestions = useMemo(
    () => buildSuggestions(symbolQuery, availableSymbols),
    [symbolQuery, availableSymbols]
  );

  const watchlistSymbols = useMemo(() => {
    if (!activeWatchlist) return [];
    return activeWatchlist.symbols;
  }, [activeWatchlist]);

  function handleAddWatchlist() {
    const trimmed = newWatchlistName.trim();
    onAddWatchlist(trimmed || nextDefaultWatchlistName);
    setNewWatchlistName("");
  }

  function handleRenameWatchlist() {
    if (!activeWatchlist) return;
    const trimmed = renameValue.trim();
    if (!trimmed) return;
    onRenameWatchlist(activeWatchlist.id, trimmed);
  }

  function handleAddSymbol(symbol) {
    if (!activeWatchlist) return;
    const trimmed = symbol.trim().toUpperCase();
    if (!trimmed) return;
    onAddSymbol(activeWatchlist.id, trimmed);
    setSymbolQuery("");
  }

  function handleDeleteWatchlist() {
    if (!activeWatchlist) return;
    onDeleteWatchlist(activeWatchlist.id);
  }

  function handleContextMenu(event, symbol) {
    event.preventDefault();
    setContextMenu({
      symbol,
      x: event.clientX,
      y: event.clientY,
    });
  }

  function handleContextAction(action) {
    if (!contextMenu || !activeWatchlist) return;
    const { symbol } = contextMenu;

    if (action === "open") {
      onSelectSymbol(symbol);
    }

    if (action === "remove") {
      onRemoveSymbol(activeWatchlist.id, symbol);
    }

    if (action.startsWith("move:")) {
      const targetId = action.replace("move:", "");
      onMoveSymbol(activeWatchlist.id, targetId, symbol);
    }

    setContextMenu(null);
  }

  return (
    <section className={`panel watchlist-panel ${isCollapsed ? "collapsed" : ""}`}>
      <div className="panel-header">
        <div>
          <h3>Watchlist</h3>
          <p className="panel-subtitle">Track & manage symbols</p>
        </div>
        <div className="panel-actions">
          <button
            type="button"
            className="icon-btn"
            onClick={() => setIsCollapsed((prev) => !prev)}
            aria-label="Toggle watchlist"
          >
            {isCollapsed ? "▸" : "▾"}
          </button>
        </div>
      </div>

      {!isCollapsed && (
        <>
          <div className="watchlist-tabs" role="tablist">
            {watchlists.map((list) => (
              <button
                key={list.id}
                type="button"
                className={`watchlist-tab ${
                  list.id === activeWatchlistId ? "active" : ""
                }`}
                onClick={() => onSwitchWatchlist(list.id)}
              >
                {list.name}
              </button>
            ))}
          </div>

          <div className="watchlist-actions">
            <div className="watchlist-field">
              <input
                type="text"
                placeholder="New watchlist name"
                value={newWatchlistName}
                onChange={(event) => setNewWatchlistName(event.target.value)}
                onKeyDown={(event) => {
                  if (event.key === "Enter") handleAddWatchlist();
                }}
              />
              <button type="button" onClick={handleAddWatchlist}>
                +
              </button>
            </div>

            <div className="watchlist-field">
              <input
                type="text"
                placeholder="Rename watchlist"
                value={renameValue}
                onChange={(event) => setRenameValue(event.target.value)}
                onKeyDown={(event) => {
                  if (event.key === "Enter") handleRenameWatchlist();
                }}
              />
              <button type="button" onClick={handleRenameWatchlist}>
                Save
              </button>
            </div>

            <div className="watchlist-field">
              <input
                type="text"
                placeholder="Search/add symbol"
                value={symbolQuery}
                onChange={(event) => setSymbolQuery(event.target.value)}
                onKeyDown={(event) => {
                  if (event.key === "Enter") handleAddSymbol(symbolQuery);
                }}
              />
              <button type="button" onClick={() => handleAddSymbol(symbolQuery)}>
                +
              </button>
            </div>

            {suggestions.length > 0 && (
              <div className="watchlist-suggestions">
                {suggestions.map((symbol) => (
                  <button
                    key={symbol}
                    type="button"
                    onClick={() => handleAddSymbol(symbol)}
                  >
                    {symbol}
                  </button>
                ))}
              </div>
            )}
          </div>

          <div className="watchlist-meta">
            <span>{watchlistSymbols.length} symbols</span>
            <button type="button" className="link-btn" onClick={handleDeleteWatchlist}>
              Delete watchlist
            </button>
          </div>

          <Watchlist
            symbols={watchlistSymbols}
            selectedSymbol={selectedSymbol}
            getStockBySymbol={getStockBySymbol}
            flashMap={flashMap}
            onSelectSymbol={onSelectSymbol}
            onRemoveSymbol={(symbol) => onRemoveSymbol(activeWatchlistId, symbol)}
            onContextMenu={handleContextMenu}
            onReorderSymbol={(dragSymbol, targetSymbol) =>
              onReorderSymbol(activeWatchlistId, dragSymbol, targetSymbol)
            }
          />
        </>
      )}

      {contextMenu && (
        <div
          className="watchlist-context"
          ref={contextMenuRef}
          style={{ left: contextMenu.x, top: contextMenu.y }}
        >
          <button type="button" onClick={() => handleContextAction("open")}>
            Open Chart
          </button>
          <button type="button" onClick={() => handleContextAction("remove")}>
            Remove from Watchlist
          </button>
          <div className="context-subtitle">Move to...</div>
          {watchlists
            .filter((list) => list.id !== activeWatchlistId)
            .map((list) => (
              <button
                key={list.id}
                type="button"
                onClick={() => handleContextAction(`move:${list.id}`)}
              >
                {list.name}
              </button>
            ))}
        </div>
      )}
    </section>
  );
}
